<?php $search=audienceText($_GET,'list_search');$segmentRows=array_values(array_filter($segments,fn($s)=>$search===''||mb_stripos($s['name'],$search)!==false));$segmentSort=($_GET['segment_sort']??'name')==='created_at'?'created_at':'name';$segmentDirection=($_GET['segment_direction']??'asc')==='desc'?'desc':'asc';$segmentOrder=in_array($_GET['segment_order']??'',['name','name_desc','newest','oldest'],true)?$_GET['segment_order']:($segmentSort==='created_at'?($segmentDirection==='desc'?'newest':'oldest'):($segmentDirection==='desc'?'name_desc':'name'));$segmentSort=in_array($segmentOrder,['newest','oldest'],true)?'created_at':'name';$segmentDirection=in_array($segmentOrder,['name_desc','newest'],true)?'desc':'asc';usort($segmentRows,fn($a,$b)=>($segmentDirection==='desc'?-1:1)*strnatcasecmp($a[$segmentSort],$b[$segmentSort]));$segmentPage=max(1,(int)($_GET['segment_page']??1));$segmentSize=(int)($_GET['segment_size']??100);if(!in_array($segmentSize,[25,50,100],true))$segmentSize=100;$segmentPage=min($segmentPage,max(1,(int)ceil(count($segmentRows)/$segmentSize))); ?>
